/**
 * GOLDEN FIXTURE for the Monster Manual 2024 NPC templates (src/data/npc-templates.ts).
 *
 * GENERATED by parsing the transcription notes read from the printed page
 * images of Docs/DnD 5e 2024 Monster Manual Alternate Cover.pdf (35 humanoid
 * NPC stat blocks, CR 10 or lower). Independent of src/data/npc-templates.ts:
 * nothing is imported from the app. `saves` and `mods` are the PRINTED MOD and
 * SAVE columns; `damage` is every printed "average (dice)" pair in block order;
 * `dcs` every printed DC in block order. Damage dice are written without spaces.
 */
